text:
Third and six plays

third_and_six &lt;- cfb_data |&gt; 
  filter (down == 3 & distance == 6)

Average run plays

rush_plays &lt;- third_and_six |&gt; 
  filter(str_detect(play_type, "Rush")) 

average_rush_plays &lt;- rush_plays |&gt; 
  summarise (
    average_yards = mean(yards_gained),
    percentage = (3508/16447) * 100
  )

Maryland specific

umd &lt;- third_and_six |&gt; 
  filter (pos_team == "Maryland")


umd_rush &lt;- umd |&gt; 
  filter(str_detect(play_type, "Rush"))


umd_average_rush &lt;- umd_rush |&gt; 
  summarise (
    average_yards = mean(yards_gained),
    percentage = (18/83) * 100
  )


umd_by_year &lt;- umd |&gt; 
  group_by(year) |&gt; 
  summarise (
    total = n()
  ) |&gt; 
  arrange (desc(total))


umd_rush_by_year &lt;- umd_rush |&gt; 
  filter(str_detect(play_type, "Rush")) |&gt; 
  group_by(year) |&gt; 
  summarise (
    total = n()
  )


ggplot() + 
  geom_bar(
    data=umd_rush_by_year, 
    aes(x=year, weight=total)) + 
  labs(
    title="Maryland has opted to pass more on third and 6 in recent years", 
    x="Years", 
    y="Rushes on third and 6")









success_rate &lt;- umd_rush |&gt; 
  filter (yards_gained &gt; 6) |&gt; 
  group_by(year) |&gt; 
    summarise (
    total = n()
  )


ggplot() + 
  geom_bar(
    data=success_rate, 
    aes(x=year, weight=total)) + 
  labs(
    title="Maryland didn't convert a third and 6 on the ground last year", 
    x="Years", 
    y="Successful rushes on third and 6")









umd_other_plays &lt;- umd |&gt; 
  filter(!str_detect(play_type, "Rush"))

other_plays_success_rate &lt;- umd_other_plays |&gt; 
  filter(yards_gained &gt; 6) |&gt; 
  group_by(year) |&gt; 
  summarise (
    total = n()
  )


ggplot() + 
  geom_bar(
    data=other_plays_success_rate, 
    aes(x=year, weight=total)) + 
  labs(
    title="Maryland has found success converting third and 6 through the air", 
    x="Years", 
    y="Successful passes on third and 6")








Third and six is typically one of the trickiest play-calling situations for any college football offensive coordinator to navigate. The down and distance is long enough that a simple run is unlikely to move the chains, but short enough that defenses still have to respect it. While general fans consider it a passing down, head coaches across the country have occasionally taken the risk of utilizing the ground game. Over the last five seasons, 21.32 percent of all third and six plays have been designed runs.
That 21 percent mark highlights a key tension in offensive strategy — the balance between predictability and surprise. Passing is clearly the more common and, statistically, more successful option in those situations, but occasionally, coaches will call a run to exploit a defensive front expecting a pass. The success of that approach often depends on context: how well the team has been running the ball that day, the formation they line up in, and the tendencies of the opposing defense. A run on third and six can look brilliant if it catches linebackers dropping into coverage — or disastrous if the defense stuffs it at the line of scrimmage.
Maryland has been right around that national average, running on roughly one-fifth of its third-and-six opportunities. Interestingly, the Terps have converted eight of their 18 rushing attempts on third and six over the last five seasons — a 44 percent success rate that suggests their ground game has been more effective than one might assume in that scenario. But after failing to convert both of their third and six rush attempts last season, Maryland has only attempted it once this season — which it successfully got the first down.
Still, the statistics alone don’t tell the whole story. My calculations don’t factor in how well a team has been running or passing the ball on a given day — or whether a team plans to go for it on fourth down anyway. That last point is key: some coaches treat third and six as part of a two-down sequence, especially near midfield or in opponent territory. In those cases, calling a run might be less about converting immediately and more about setting up a manageable fourth down situation. If a team’s ground game has been consistently productive, that kind of play-calling can be a calculated and efficient approach rather than a conservative one.

Penn State (couldn’t figure out how to only show the years with data in the bar chart)

psu_season_games &lt;- logs |&gt; 
  filter(Team == "Penn State") |&gt; 
  group_by (Season) |&gt; 
  summarise(all_games =n())

psu_season_games_under_100_wins &lt;- logs |&gt; 
  filter(Result == "W", RushYds &lt; 100, Team == "Penn State") |&gt; 
  group_by (Season) |&gt; 
  summarise(low_rush_wins =n())

psu_combined_games &lt;- psu_season_games |&gt; 
  inner_join(psu_season_games_under_100_wins, join_by(Season)) |&gt; 
  mutate(pct_low_rush_wins = low_rush_wins/all_games * 100)

ggplot() + 
  geom_bar(
    data=psu_combined_games, 
    aes(x=Season, weight=pct_low_rush_wins)) + scale_x_continuous(breaks = ~ axisTicks(., log = FALSE)) +
  labs(
    title="Penn State seasons based on percentage of wins under 100 rushing yards", 
    x="Seasons", 
    y="Percentage of wins under 100 rushing yards") + 
  theme_minimal()

Individual NCAA teams

teams_season_games &lt;- logs |&gt; 
  group_by (Team) |&gt; 
  summarise(all_games =n())

teams_season_games_under_100_wins &lt;- logs |&gt; 
  filter(Result == "W", RushYds &lt; 100) |&gt; 
  group_by (Team) |&gt; 
  summarise(low_rush_wins =n())

teams_combined_games &lt;- teams_season_games |&gt; 
  inner_join(teams_season_games_under_100_wins, join_by(Team)) |&gt; 
  mutate(pct_low_rush_wins = low_rush_wins/all_games * 100) |&gt; 
  arrange(desc(pct_low_rush_wins))

ten_teams &lt;- teams_combined_games |&gt; 
  arrange(desc(pct_low_rush_wins)) |&gt; 
  top_n(10)

Selecting by pct_low_rush_wins

ggplot() + 
  geom_bar(
    data=ten_teams, 
    aes(
      x=reorder(Team, -pct_low_rush_wins),
      weight=pct_low_rush_wins)
  ) + 
  labs(
    title="Top 10 teams based on percentage of wins under 100 rushing yards", 
    x="Seasons", 
    y="Percentage of wins under 100 rushing yards") + 
  theme_minimal() + 
  coord_flip()

Power Five Teams Only

power_five_teams_season_games &lt;- logs |&gt; 
  filter(Conference == "Big Ten Conference" | Conference == "Southeastern Conference" | Conference == "Atlantic Coast Conference" | Conference == "Big 12 Conference" | Conference == "Pac-12 Conference") |&gt; 
  group_by (Team) |&gt; 
  summarise(all_games =n())

power_five_teams_season_games_under_100_wins &lt;- logs |&gt; 
  filter(Result == "W", RushYds &lt; 100, Conference == "Big Ten Conference" | Conference == "Southeastern Conference" | Conference == "Atlantic Coast Conference" | Conference == "Big 12 Conference" | Conference == "Pac-12 Conference") |&gt; 
  group_by (Team) |&gt; 
  summarise(low_rush_wins =n())

power_five_teams_combined_games &lt;- power_five_teams_season_games |&gt; 
  inner_join(power_five_teams_season_games_under_100_wins, join_by(Team)) |&gt; 
  mutate(pct_low_rush_wins = low_rush_wins/all_games * 100) |&gt; 
  arrange(desc(pct_low_rush_wins))

top_ten_power_five_teams &lt;- power_five_teams_combined_games |&gt; 
  arrange(desc(pct_low_rush_wins)) |&gt; 
  top_n(10)

Selecting by pct_low_rush_wins

ggplot() + 
  geom_bar(
    data=top_ten_power_five_teams, 
    aes(
      x=reorder(Team, -pct_low_rush_wins),
      weight=pct_low_rush_wins)
  ) + 
  labs(
    title="Top 10 Power Five teams based on percentage of wins under 100 rushing yards", 
    x="Seasonl", 
    y="Percentage of wins under 100 rushing yards") + 
  theme_minimal() +
  coord_flip()

